#include <array>
#include <iostream>
#include <string_view>

int main() {
    constexpr std::array<std::string_view, 5> stages{
        "source", "preprocess", "compile", "assemble", "link"
    };
    for (std::size_t i = 0; i < stages.size(); ++i) {
        std::cout << i + 1 << ". " << stages[i] << '\n';
    }
}
